function exportMedReviewData() {
  try {
    const payload = {
      app: 'MedReview',
      version: 2,
      exportedAt: new Date().toISOString(),
      retention: getTargetRetention(),
      state: state,
      evalHistory: getStoredEvalHistory(),
      studyTimeMs: getStoredStudyTimeMs()
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'medreview-backup-' + new Date().toISOString().split('T')[0] + '.json';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  } catch (e) {
    alert('Erro ao exportar: ' + e.message);
  }
}

function importMedReviewData(file) {
  const reader = new FileReader();
  reader.onload = (ev) => {
    try {
      const payload = JSON.parse(ev.target.result);
      if (!payload || payload.app !== 'MedReview' || !payload.state) {
        alert('Arquivo inválido — não parece um backup do MedReview.');
        return;
      }
      if (!confirm('Importar backup de ' + (payload.exportedAt || '?') + '? Isso substitui o progresso atual.')) return;
      state = payload.state;
      migrateAllCardsFSRS();
      saveState();
      try { localStorage.setItem(EVAL_HISTORY_KEY, JSON.stringify(payload.evalHistory || [])); } catch (e) {}
      try { localStorage.setItem(STUDY_TIME_KEY, String(payload.studyTimeMs || 0)); } catch (e) {}
      if (payload.retention) setTargetRetention(payload.retention);
      alert('✅ Backup importado com sucesso!');
      renderRoute();
    } catch (e) {
      alert('Erro ao importar: ' + e.message);
    }
  };
  reader.readAsText(file);
}

